 if(decision==='Request changes'){d.state='Changes requested';d.returnNote=voText(note);d.returnEventId=voNotify(d,'Onboarding changes requested: '+t.service,note,s.submittedBy,'vendor-onboarding-intake',{sourceState:d.state});}
 else if(ownerStage){d.state='Risk review';d.eventId=voNotify(d,'Review onboarding diligence plan: '+t.service,note,d.riskReviewerId,'vendor-onboarding-intake',{type:'approval',sourceState:d.state,due:s.snapshot.reviewDue});}
 else{d.state='Due diligence';d.acceptedAt=voNow();d.acceptedBy=actor.id;d.acceptedRevision=d.revision;voNotify(d,'Vendor due diligence assigned: '+t.service,'Named questionnaires and document requests are ready. Service activation remains subject to accepted responses, current reviewed documents and requirement conclusions.',d.ownerId,'vendor-onboarding-status',{actionable:false});}
 voLog(d,decision,{note:voText(note),receiptId:receipt.id});save();return d;
