function voDocumentItem(d,id){const item=d.documents.find(item=>item.id===id);requireValue(item,'This document request is unavailable.');return item;}
function voDocumentAllowed(versionId,d){const v=docVersion(versionId),file=v&&recRead('document',v.documentId);return !!file&&!file.archived&&docVisible(file)&&docCanLink(file,{type:'engagement',id:d.engagementId})&&(file.classification!=='Restricted'||file.ownerId===recActor().id);}
