 docLinkVersion(v.id,{type:'engagement',id:d.engagementId},'onboarding:'+item.id);if(item.documentVersionId)item.history.push({documentVersionId:item.documentVersionId,approvalRequestId:item.approvalRequestId,validThrough:item.validThrough,noExpiryReason:item.noExpiryReason,changedAt:voNow(),changedBy:recActor().id});Object.assign(item,{documentVersionId:v.id,approvalRequestId:approval?.id||'',validThrough,noExpiryReason,linkedAt:voNow(),linkedBy:recActor().id,reuseReason:voText(input.reuseReason)});voLog(d,'Linked document: '+item.title,{documentVersionId:v.id,approvalRequestId:approval?.id||''});if(voDocumentStatus(d,item).ready)voResolve(item.eventId,'Current document and independent approval supplied');save();return item;
