const voPriorVendorGate=wf29VendorGate;
wf29VendorGate=function(t){const original=voPriorVendorGate(t),d=voForEngagement(t.id);if(d){const readiness=voReadiness(d,original);return {...original,clear:original.clear&&readiness.ready,onboarding:readiness};}return ['Onboarding','Due diligence'].includes(t.status)?{...original,clear:false,onboarding:{ready:false,issues:['Complete the onboarding dossier for this first-time service.']}}:original;};
const voPriorLifecycleSubmit=wf29SubmitVendor;
wf29SubmitVendor=function(id){const t=wf29Record('engagement',id),draft=wf29Draft('vendor-review',id),actor=recActor();requireValue(draft,'Start the service review first.');requireValue(draft.values.requestedBy===actor.name,'The current identity must be the named review preparer. Switch identity or correct the preparer.');requireValue(voCanPrepare(actor.id,t.orgScopeId,t,'vendors.edit'),'The current identity cannot prepare this service review.');const reviewer=recUserId(draft.values.reviewer);requireValue(gvDecision(reviewer,'vendors.approve',t.orgScopeId,S.asOf,{makerId:actor.id}).allowed,'Choose an independent reviewer with current service approval authority.');const d=voForEngagement(id),needsGate=['Activate service','Resume service'].includes(draft.values.requestType),ready=needsGate&&d?voReadiness(d):null;if(needsGate)requireValue(wf29VendorGate(t).clear,ready?.issues.join(' ')||'Complete the onboarding dossier and current assurance before requesting activation.');voPriorLifecycleSubmit(id);const request=wf29State().vendorReviews.filter(r=>r.engagementId===id).at(-1);if(ready){request.onboardingBasis=clone(ready.basis);request.onboardingBasisHash=ready.basisHash;save();}return request;};
const voPriorLifecycleDecision=wf29VendorDecision;
wf29VendorDecision=function(form){const request=wf29State().vendorReviews.find(r=>r.id===form.dataset.id);requireValue(request,'The lifecycle review is unavailable.');const t=wf29Record('engagement',request.engagementId),v=values(form),actor=recActor();requireValue(v.reviewer===actor.name&&request.reviewer===actor.name,'Only the assigned reviewer acting under their own identity can decide this request.');requireValue(gvDecision(actor.id,'vendors.approve',t.orgScopeId,S.asOf,{makerId:recUserId(request.requestedBy)}).allowed,'Current independent service approval authority is required.');if(v.decision==='Approve request'&&['Activate service','Resume service'].includes(request.requestType)){const d=voForEngagement(t.id),readiness=d&&voReadiness(d);requireValue(wf29VendorGate(t).clear,readiness?.issues.join(' ')||'The onboarding and assurance gates are incomplete.');if(d)requireValue(request.onboardingBasisHash&&readiness.basisHash===request.onboardingBasisHash,'The diligence source changed after activation was requested. Request a revised lifecycle review.');}return voPriorLifecycleDecision(form);};

