 const issues=voIssues(x,{engagementId:d.engagementId,preparerId:d.createdBy});return `<div class="vo-section-lead"><span class="vo-kicker">Review the intake</span><h2>Submit the dossier for owner confirmation</h2><p>The owner confirms business scope. The independent risk reviewer approves the diligence plan and launches the named assignments.</p></div>${voSummary(x)}<div class="vo-review-plan"><div><b>${x.requirements.filter(r=>r.include).length}</b><span>applicable requirements</span></div><div><b>${x.questionnaires.filter(q=>q.enabled).length}</b><span>named questionnaires</span></div><div><b>${x.documents.filter(item=>item.required).length}</b><span>required documents</span></div></div>${d.dossierId?voArea('correctionReason','What changed in this returned intake?',x.correctionReason,'maxlength="2000"'):''}${voArea('note','Context for the owner and risk reviewer (optional)',x.note,'maxlength="2000"')}${issues.length?`<section class="vo-validation"><h3>${issues.length} item${issues.length===1?'':'s'} to complete</h3><ul>${issues.map(message=>`<li>${e(message)}</li>`).join('')}</ul><p>Choose a step above to complete it. Your saved work stays in this draft.</p></section>`:notice('The intake is ready. Submission creates an onboarding record; it does not activate the service.','mini')}`;
