function voSummary(x){const vendor=S.vendors.find(v=>v.id===x.supplierId),pairs=[['Supplier',x.supplierName||vendor?.name],['Country / registration',[x.country,x.registrationId].filter(Boolean).join(' · ')],['Service',x.service],['Accountable location',orgName(x.orgScopeId)],['Internal owner',voName(x.ownerId)],['Risk reviewer',voName(x.riskReviewerId)],['Supplier respondent',[x.contactName,x.contactRole,x.contactEmail].filter(Boolean).join(' · ')],['Service boundary',x.description],['Business purpose',x.businessPurpose],['Criticality',x.criticality+' · '+x.criticalityReason],['Data scope',x.dataContext],['Personal data',x.personalData],['Proposed start / first review',[x.proposedStart,x.renewal].filter(Boolean).map(date).join(' / ')]];return `<dl class="vo-facts">${pairs.map(([key,value])=>`<div><dt>${e(key)}</dt><dd>${e(value||'Not captured')}</dd></div>`).join('')}</dl>`;}
