function voActivationEntry(id){const t=wf29Record('engagement',id),d=voForEngagement(id);if(!d&&['Onboarding','Due diligence'].includes(t.status)){voStart(id);return;}if(d&&!voReadiness(d).ready){go(voRoute(d.id));return;}wf29StartVendor(id,t.status==='Suspended'?'Resume service':'Activate service');}
function voMigrateLegacy(id){voInit();if(S.vendorOnboarding.drafts[id])return S.vendorOnboarding.drafts[id];const old=S.journeyDrafts?.[id];if(old?.kind!=='vendor')return null;const x=old.data||{},values=voEmptyValues(x.orgScopeId||'');Object.assign(values,{supplierId:x.supplier||'new',supplierName:x.supplierName||'',country:x.country||'Nigeria',contactEmail:x.contact||'',service:x.service||'',dataContext:x.data||'',personalData:x.privacy||'Unknown',ownerId:recUserId(x.owner)||recActor().id,responseLeadId:recUserId(x.owner)||recActor().id,criticality:x.criticality||'High',renewal:x.renewal||values.renewal});const draft={id,values,step:1,engagementId:'',createdBy:recActor().id,createdAt:voNow(),origin:'Resumed earlier supplier setup'};S.vendorOnboarding.drafts[id]=draft;delete S.journeyDrafts[id];save();return draft;}
