const voPriorWorkItems=workItems;
workItems=function(){const rows=voPriorWorkItems();for(const d of voInit().dossiers.filter(d=>voScopeOK(d.orgScopeId))){const x=d.submission.snapshot,t=recRead('engagement',d.engagementId);if(!t)continue;let owner,due,kind;if(d.state==='Owner confirmation'){owner=d.ownerId;due=x.ownerDue;kind='Vendor owner confirmation';}else if(d.state==='Risk review'){owner=d.riskReviewerId;due=x.reviewDue;kind='Vendor intake risk review';}else if(d.state==='Changes requested'){owner=d.submission.submittedBy;due=x.reviewDue;kind='Vendor intake correction';}if(owner)rows.push({id:'VO-'+d.id+'-'+d.revision+'-'+d.state,title:kind+' · '+t.service,kind,owner:voName(owner),ownerId:owner,due,status:'Open',ref:t.id,orgScopeId:d.orgScopeId,source:'vendor-onboarding',route:voRoute(d.id)});if(d.state==='Due diligence')for(const item of d.documents){const status=voDocumentStatus(d,item);if(!status.ready&&status.state!=='Awaiting review')rows.push({id:'VO-DOC-'+d.id+'-'+item.id,title:item.title+' · '+t.service,kind:'Vendor document request',owner:voName(item.coordinatorId),ownerId:item.coordinatorId,due:item.due,status:'Open',ref:t.id,orgScopeId:d.orgScopeId,source:'vendor-onboarding-document',route:voRoute(d.id)+'&tab=documents'});}}return rows;};
const voPriorResolved=nResolved;
nResolved=function(event){if(event.sourceWorkflow?.startsWith('vendor-onboarding')){const d=voInit().dossiers.find(d=>d.id===event.sourceDossierId&&d.engagementId===event.sourceId);if(!d)return false;if(event.sourceWorkflow==='vendor-onboarding-document'){const item=d.documents.find(item=>item.id===event.sourceItemId);return !!item&&voDocumentStatus(d,item).ready;}if(event.sourceWorkflow==='vendor-onboarding-intake')return Number(event.sourceRevision)!==d.revision||event.sourceState!==d.state;}return voPriorResolved(event);};
